/**
 * The font files every generated site ships, keyed by deploy-relative path (no leading slash), as bytes. The deploy routes
 * write them next to the rendered pages; the HTML references them through SITE_FONT_PATHS.
 */
export function siteFontFiles(): Record<string, Buffer> {
  return {
    [SITE_FONT_PATHS.hebrew.slice(1)]: Buffer.from(HEEBO_HEBREW_WOFF2_BASE64, 'base64'),
    [SITE_FONT_PATHS.latin.slice(1)]: Buffer.from(HEEBO_LATIN_WOFF2_BASE64, 'base64'),
    [SITE_FONT_PATHS.licence.slice(1)]: Buffer.from(HEEBO_OFL_TEXT, 'utf8'),
  };
}
